import triton.language as tl


@triton.jit
def _bn_reduce_kernel(
    x_ptr,
    partial_sum_ptr,
    partial_sq_ptr,
    C,
    HW,
    stride_b,
    stride_c,
    B: tl.constexpr,
    BLOCK_HW: tl.constexpr,
):
    pid_c = tl.program_id(0)
    pid_b = tl.program_id(1)
    base = pid_b.to(tl.int64) * stride_b + pid_c.to(tl.int64) * stride_c
    acc_sum = 0.0
    acc_sq = 0.0
    for hw_start in range(0, HW, BLOCK_HW):
        offs = hw_start + tl.arange(0, BLOCK_HW)
        mask = offs < HW
        x = tl.load(x_ptr + base + offs, mask=mask, other=0.0).to(tl.float32)
        acc_sum += tl.sum(x, axis=0)
        acc_sq += tl.sum(x * x, axis=0)
    out_idx = pid_c * B + pid_b
    tl.store(partial_sum_ptr + out_idx, acc_sum)
    tl.store(partial_sq_ptr + out_idx, acc_sq)


@triton.jit
def _bn_stats_kernel(
    partial_sum_ptr,
    partial_sq_ptr,
    scale_ptr,
    shift_ptr,
    weight_ptr,
    bias_ptr,
    inv_count,
    eps,
    B: tl.constexpr,
    BLOCK_B: tl.constexpr,
):
    pid_c = tl.program_id(0)
    offs_b = tl.arange(0, BLOCK_B)
    mask = offs_b < B
    s = tl.load(partial_sum_ptr + pid_c * B + offs_b, mask=mask, other=0.0)
    sq = tl.load(partial_sq_ptr + pid_c * B + offs_b, mask=mask, other=0.0)
    total_sum = tl.sum(s, axis=0)
    total_sq = tl.sum(sq, axis=0)
    mean_val = total_sum * inv_count
    var_val = total_sq * inv_count - mean_val * mean_val
    w = tl.load(weight_ptr + pid_c)
    bi = tl.load(bias_ptr + pid_c)
    inv_std = 1.0 / tl.sqrt(var_val + eps)
    scale_val = w * inv_std
    shift_val = bi - mean_val * scale_val
    tl.store(scale_ptr + pid_c, scale_val)
    tl.store(shift_ptr + pid_c, shift_val)


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 4096, "warp_size": 32}, num_warps=8),
    ],
    key=["total_elements"],
)
@triton.jit
def _bn_normalize_flat_kernel(
    x_ptr,
    out_ptr,
    scale_ptr,
    shift_ptr,
    C,
    HW,
    total_elements,
    BLOCK_SIZE: tl.constexpr,
    warp_size: tl.constexpr,
):
    pid = tl.program_id(0)
    start = pid * BLOCK_SIZE
    offs = start + tl.arange(0, BLOCK_SIZE)
    mask = offs < total_elements
    c = (offs // HW) % C
    x = tl.load(x_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    scale = tl.load(scale_ptr + c, mask=mask, other=0.0)
    shift = tl.load(shift_ptr + c, mask=mask, other=0.0)
    y = x * scale + shift
    tl.store(out_ptr + offs, y.to(tl.float32), mask=mask)


class Model(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.eps = 1e-5
        self.momentum = 0.1
        self._moved = False
        self._bufs_ready = False

    def _move_params(self, device):
        self.weight.data = self.weight.data.to(device, dtype=torch.float32).contiguous()
        self.bias.data = self.bias.data.to(device, dtype=torch.float32).contiguous()
        self.running_mean = self.running_mean.to(
            device, dtype=torch.float32
        ).contiguous()
        self.running_var = self.running_var.to(device, dtype=torch.float32).contiguous()
        self._moved = True

    def _alloc_bufs(self, B, C, device):
        self._partial_sum = torch.empty((C, B), device=device, dtype=torch.float32)
        self._partial_sq = torch.empty((C, B), device=device, dtype=torch.float32)
        self._scale = torch.empty(C, device=device, dtype=torch.float32)
        self._shift = torch.empty(C, device=device, dtype=torch.float32)
        self._bufs_ready = True

    def forward(self, x):
        device = x.device
        if not self._moved:
            self._move_params(device)
        x = x.to(dtype=torch.float32).contiguous()
        B, C, H, W = x.shape
        HW = H * W
        stride_b = x.stride(0)
        stride_c = x.stride(1)
        total_elements = B * C * HW

        if not self._bufs_ready:
            self._alloc_bufs(B, C, device)

        if self.training:
            _bn_reduce_kernel[(C, B)](
                x,
                self._partial_sum,
                self._partial_sq,
                C,
                HW,
                stride_b,
                stride_c,
                B=B,
                BLOCK_HW=8192,
                num_warps=8,
            )
            _bn_stats_kernel[(C,)](
                self._partial_sum,
                self._partial_sq,
                self._scale,
                self._shift,
                self.weight,
                self.bias,
                1.0 / (B * HW),
                self.eps,
                B=B,
                BLOCK_B=triton.next_power_of_2(B),
                num_warps=4,
            )
        else:
            inv_std = 1.0 / torch.sqrt(self.running_var + self.eps)
            self._scale.copy_(self.weight * inv_std)
            self._shift.copy_(self.bias - self.running_mean * self._scale)

        out = torch.empty_like(x)
        grid = lambda META: (triton.cdiv(total_elements, META["BLOCK_SIZE"]),)
        _bn_normalize_flat_kernel[grid](
            x,
            out,
            self._scale,
            self._shift,
            C,
            HW,
            total_elements,
        )
        return out


